def _decode() -> dict[str, Any]:
    return json.loads(zlib.decompress(base64.b85decode(_LITERAL.encode())).decode())

CATALOG_0010: dict[str, Any] = _decode()
DDL_SHA256 = "cf0975f9e03d98587c5d5e671a335fb17a0ac5703198000b6b3dceeae4e1b9b2"
CATALOG_ATTESTATION = "22b38890d481f1a75b8ba9424753f2ffe3b2c3cb912be3f015c3187a9e58d33a"

def catalog_attestation() -> str:
    return hashlib.sha256(json.dumps(CATALOG_0010, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def marker_ddl() -> str:
    """Literal marker declaration recorded by the accepted 0010 inventory."""
    marker = CATALOG_0010["marker"]
    columns = ", ".join(
        f'{column["name"]} {column["type"]} NOT NULL'
        for column in marker["columns"]
    )
    return f'CREATE TABLE {marker["table"]} ({columns}, PRIMARY KEY (version))'


